// Validate and extract input parameters
const input = $input.first().json;
const body = input.body || {};

// Required fields
const requiredFields = ['project_id', 'price_id', 'customer_email', 'urls'];
const missing = requiredFields.filter(f => !body[f]);

if (missing.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Missing required fields: ${missing.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Validate URLs
if (!body.urls.success || !body.urls.cancel) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'urls.success and urls.cancel are required',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Extract and normalize data
return [{
  json: {
    valid: true,
    project_id: body.project_id,
    price_id: body.price_id,
    customer_email: body.customer_email,
    callbacks: body.callbacks || {},
    urls: body.urls,
    metadata: body.metadata || {},
    options: body.options || {}
  }
}];

// Check if project was found
const dbResults = $('Get Project Config').all();
const inputData = $('Validate Input').first().json;

if (!dbResults || dbResults.length === 0 || !dbResults[0].json.project_id) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Project '${inputData.project_id}' not found or inactive`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

const project = dbResults[0].json;

// Parse prices JSON
let prices = {};
try {
  prices = typeof project.prices === 'string' ? JSON.parse(project.prices) : project.prices;
} catch (e) {
  prices = {};
}

return [{
  json: {
    found: true,
    project: {
      project_id: project.project_id,
      display_name: project.display_name,
      secret_key: project.secret_key,
      webhook_secret: project.webhook_secret,
      prices: prices
    },
    input: inputData
  }
}];

// Prepare Stripe API call with dynamic auth
const data = $input.first().json;
const secretKey = data.project.secret_key;

// Build form-urlencoded body as string
const params = new URLSearchParams();
params.append('mode', 'subscription');
params.append('customer_email', data.input.customer_email);
params.append('line_items[0][price]', data.input.price_id);
params.append('line_items[0][quantity]', '1');
params.append('success_url', `${data.input.urls.success}?session_id={CHECKOUT_SESSION_ID}`);
params.append('cancel_url', data.input.urls.cancel);
params.append('metadata[project_id]', data.project.project_id);

// Add callbacks to metadata
if (data.input.callbacks.success) {
  params.append('metadata[callback_success]', data.input.callbacks.success);
}
if (data.input.callbacks.renewal) {
  params.append('metadata[callback_renewal]', data.input.callbacks.renewal);
}
if (data.input.callbacks.failure) {
  params.append('metadata[callback_failure]', data.input.callbacks.failure);
}
if (data.input.callbacks.cancel) {
  params.append('metadata[callback_cancel]', data.input.callbacks.cancel);
}

// Add custom metadata
if (data.input.metadata) {
  Object.entries(data.input.metadata).forEach(([key, value]) => {
    params.append(`metadata[${key}]`, String(value));
  });
}

// Add trial if specified
if (data.input.options.trial_days) {
  params.append('subscription_data[trial_period_days]', String(data.input.options.trial_days));
}

// Add coupon if specified
if (data.input.options.coupon_code) {
  params.append('discounts[0][coupon]', data.input.options.coupon_code);
}

// Add promotion codes if enabled
if (data.input.options.allow_promotion_codes) {
  params.append('allow_promotion_codes', 'true');
}

return [{
  json: {
    authHeader: `Bearer ${secretKey}`,
    bodyString: params.toString()
  }
}];

// Format success response
const stripeResponse = $input.first().json;

if (stripeResponse.statusCode === 200 && stripeResponse.body) {
  const session = stripeResponse.body;
  return [{
    json: {
      success: true,
      checkout_url: session.url,
      session_id: session.id,
      expires_at: session.expires_at
    }
  }];
}

// Handle Stripe error
const error = stripeResponse.body?.error || {};
return [{
  json: {
    success: false,
    error: {
      code: stripeResponse.statusCode || 500,
      message: error.message || 'Failed to create checkout session',
      type: error.type || 'api_error',
      stripe_code: error.code || null
    }
  }
}];
